// CSD_RATIONALE_BEGIN
// Root cause analysis of attempt 2 (10.2% accuracy):
//   (A) Dead-end "!!!" floods: Phase 2 suppressed ALL span closure (no
//       IsCompletePrefix check). Once the expression was complete the grammar
//       admitted no further tokens, so AdaptiveConstrainedStep returned EOS and
//       the span was left open — then CloseSpanWithinBudget was never called
//       (gated on `steps < maxSteps`, but the loop had used the full budget).
//   (B) Intermediate-span wrong answers: model opened << for partial
//       intermediate calculations (e.g. <<n1 + n2>>); Phase 2 kept generating
//       inside that span past the complete point until EOS or budget.
//   (C) 3 unterminated spans: EOS hit inside constrained mode with post-loop
//       guard `steps < maxSteps` already false.
//
// Fix — three-part change:
//   1. Allow span closure via CloseSpanIfComplete at EVERY constrained step,
//      but guard with a minimum span-token count (>= 4) to prevent single-
//      token premature close (e.g. "n0" closing after 1 token).
//   2. After a span closes, CONTINUE the outer loop (do NOT break). The
//      model may open multiple << >> spans; the evaluator takes the last
//      complete one, so intermediate wrong spans are harmless.
//   3. Unconditionally call CloseSpanWithinBudget at the end whenever a span
//      is still open, using ALL remaining steps — not gated on a prior
//      budget check that may be false.
//
// Guidance: direct the model to use Python integer arithmetic operators
// (// for division, ** for power, int() for truncation) in the final formula.
// This targets the large semantic-mismatch cluster (41 wrong-but-valid examples)
// where the model used / instead of // or omitted int() wraps.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: implication is vacuous (insideConstrainedOut = false)
//   until RenderedEndsWith detects "<<", at which point we set
//   currentConstrainedOut := [] and parser.IsValidPrefix([]) holds by the
//   method precondition `parser.IsValidPrefix([])`.
//
//   Inside-span close branch: CloseConstrainedSpan sets insideConstrainedOut
//   := false, making the implication vacuously true; and requires
//   parser.IsCompletePrefix which is stronger than IsValidPrefix.
//
//   Inside-span constrained-step branch: AdaptiveConstrainedStep returns
//   eosToken or a token t such that parser.IsValidPrefix(currentConstrainedOut
//   + [t]). On eosToken we break without modifying span state. On a normal
//   token, AppendConstrainedToken's postcondition guarantees the updated
//   currentConstrainedOut remains parser-valid.
//
//   Post-loop CloseSpanWithinBudget: its postcondition guarantees
//   `insideOut ==> parser.IsValidPrefix(currentOut)` and
//   `!insideOut ==> currentOut == []`.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Outside-span branch: steps incremented by 1 before any append; on EOS no
//   token appended; on normal token generated grows by exactly 1; bound holds.
//
//   Inside-span close branch: steps += 1; CloseConstrainedSpan appends ">>"
//   (one token) to generated; both grow by 1; bound holds.
//
//   Inside-span constrained-step branch: steps += 1; on EOS no append; on
//   normal token AppendConstrainedToken appends exactly one token to generated;
//   bound holds.
//
//   Post-loop: closeBudget = maxSteps - steps; CloseSpanWithinBudget grows
//   generated by at most closeBudget; we set steps := maxSteps; so
//   |generated| <= |generatedPrefix| + old_steps + closeBudget
//             = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math problem with complete step-by-step reasoning in plain text. At the very end, write the final answer as a Python expression inside << >>. Use ** for exponentiation, // for integer division (not /), and int() to truncate a result to an integer. Use only the variable names that appear in the problem. Do not open << >> until you are writing the final answer. Example endings: <<int(n * r // 60)>> or <<n0 * (r + 1) ** d>>.");

var steps: nat := 0;
var minSpanLen: nat := 4;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else {
    var spanLen := |currentConstrainedOut|;
    if parser.IsCompletePrefix(currentConstrainedOut) && spanLen >= minSpanLen {
      // Span is complete and long enough — close it and keep going
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
      // Continue outer loop — model may open another << >> (last one wins)
    } else {
      // Generate next constrained token
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var aG, aI, aC := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := aG;
      insideConstrainedOut := aI;
      currentConstrainedOut := aC;
    }
  }
}

// Unconditionally close any still-open span with all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget);
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

